import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal } from './invoices.js';
import { roundCents } from './money.js';

/**
 * List invoices that are overdue as of a given date.
 * @param {Array} invoices - all invoices to search through
 * @param {string} asOf - cutoff date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 *          sorted by daysOverdue descending (most overdue first)
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Summarize VAT by rate across invoices.
 * @param {Array} invoices - all invoices to process
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 *          sorted by rate descending (high to low)
 */
export function vatSummary(invoices) {
  const vatByRate = {};

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const lineAmount = lineTotal(line);
        const lineDiscount = roundCents(lineAmount * ((line.discountPercent ?? 0) / 100));
        const lineAfterDiscount = lineAmount - lineDiscount;
        const lineVat = roundCents(lineAfterDiscount * (line.vatRate / 100));

        if (!vatByRate[line.vatRate]) {
          vatByRate[line.vatRate] = { rate: line.vatRate, base: 0, vat: 0 };
        }

        vatByRate[line.vatRate].base += lineAfterDiscount;
        vatByRate[line.vatRate].vat += lineVat;
      });
    });

  return Object.values(vatByRate).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * 0.04% of the amount still due for every day overdue, 0 if not overdue.
 * @param {{ dueDate: string, status: string, payments?: Array }} invoice
 * @param {string} asOf - cutoff date in YYYY-MM-DD format
 * @returns {number} - late fee in cents
 */
export function lateFee(invoice, asOf) {
  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) {
    return 0;
  }

  const due = balanceDue(invoice);
  const fee = roundCents(due * 0.0004 * daysOverdue);
  return Math.max(0, fee);
}

