test('vatSummary groups VAT by rate', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-20',
    lines: [{ sku: 'PRINT-A4', qty: 100 }],
  });

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2024-0001']);

  const result = vatSummary([issued1.value, issued2.value]);

  assert.equal(result.length, 2);
  const rate21 = result.find((r) => r.rate === 21);
  const rate9 = result.find((r) => r.rate === 9);
  assert.ok(rate21);
  assert.ok(rate9);
  assert.ok(rate21.base > 0);
  assert.ok(rate21.vat > 0);
  assert.ok(rate9.base > 0);
  assert.ok(rate9.vat > 0);
});

