test('vatSummary calculates base as amount after discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = vatSummary([issuedResult.value]);

  // DES-HOUR: 10 * 8500 = 85000
  // Discount: 85000 * 10% = 8500
  // Base: 85000 - 8500 = 76500
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 76500);
});

test('vatSummary calculates VAT correctly per rate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = vatSummary([issuedResult.value]);

  // Base: 76500
  // VAT at 21%: 76500 * 21 / 100 = 16065
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].vat, 16065);
});

