test('lateFee calculates fee for 1 day overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Due date: 2024-01-29
  const totals = invoiceTotals(issuedResult.value);
  const fee = lateFee(issuedResult.value, '2024-01-30');

  // Fee = total * 0.0004 * 1
  const expectedFee = Math.round(totals.total * 0.0004);
  assert.equal(fee, expectedFee);
});

test('lateFee calculates fee for multiple days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Due date: 2024-01-29
  const totals = invoiceTotals(issuedResult.value);
  const fee = lateFee(issuedResult.value, '2024-02-15');

  // Days overdue: 17 (2024-02-15 - 2024-01-29)
  // Fee = total * 0.0004 * 17
  const expectedFee = Math.round(totals.total * 0.0004 * 17);
  assert.equal(fee, expectedFee);
});

test('lateFee uses balance due, not total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const totals = invoiceTotals(issuedResult.value);

  // Record a payment of half the total
  const paymentResult = recordPayment(issuedResult.value, { amount: Math.floor(totals.total / 2), date: '2024-01-20' });

  // Due date: 2024-01-29
  const fee = lateFee(paymentResult.value, '2024-01-30');

  // Balance due: ~51425 (half of 102850)
  // Fee = 51425 * 0.0004 * 1 ≈ 20 cents
  assert.ok(fee > 0);
  assert.ok(fee < 30);
});

