test('lateFee scales with amount due', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2024-0001']);

  const fee1 = lateFee(issued1.value, '2024-01-30');
  const fee2 = lateFee(issued2.value, '2024-01-30');

  // fee2 should be roughly 10x fee1
  assert.ok(fee2 > fee1);
  assert.ok(Math.abs(fee2 / fee1 - 10) < 1);
});

test('lateFee scales with days overdue', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);

  const fee1Day = lateFee(issuedResult.value, '2024-01-30');
  const fee7Days = lateFee(issuedResult.value, '2024-02-05');
  const fee30Days = lateFee(issuedResult.value, '2024-02-28');

  // Fees should scale linearly with days
  assert.ok(fee7Days > fee1Day);
  assert.ok(fee30Days > fee7Days);
  assert.ok(Math.abs(fee7Days / fee1Day - 7) < 1);
  assert.ok(Math.abs(fee30Days / fee1Day - 30) < 2);
});

