  const inv4 = issueInvoice(createInvoice({ customerId: 'C-004', issueDate: '2024-01-15', lines: [{ sku: 'PRINT-A4', qty: 10 }] }).value, ['INV-2024-0001', 'INV-2024-0002', 'INV-2024-0003']).value;

  const result = dashboard([inv1, inv2, inv3, inv4], '2024-02-01');

  assert.equal(result.topCustomers.length, 3);
  // C-003 (DES-HOUR qty 10) > C-001 (STICKER qty 100) > C-002 (STICKER qty 50)
  assert.equal(result.topCustomers[0].customerId, 'C-003');
  assert.equal(result.topCustomers[1].customerId, 'C-001');
  assert.equal(result.topCustomers[2].customerId, 'C-002');
  assert.ok(result.topCustomers[0].due >= result.topCustomers[1].due);
  assert.ok(result.topCustomers[1].due >= result.topCustomers[2].due);
});

test('dashboard with fewer than 3 customers', () => {
  const inv1 = issueInvoice(createInvoice({ customerId: 'C-001', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 10 }] }).value, []).value;
  const inv2 = issueInvoice(createInvoice({ customerId: 'C-002', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 10 }] }).value, ['INV-2024-0001']).value;

  const result = dashboard([inv1, inv2], '2024-02-01');

  assert.equal(result.topCustomers.length, 2);
});

test('dashboard with no outstanding invoices', () => {
  const invoices = [
    createInvoice({ customerId: 'C-001', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 10 }] }).value,
  ];

  const result = dashboard(invoices, '2024-02-01');

  assert.equal(result.outstanding, 0);
  assert.equal(result.overdue.count, 0);
  assert.equal(result.topCustomers.length, 0);
});

test('dashboard excludes paid invoices from outstanding', () => {
  const invoiceResult = createInvoice({ customerId: 'C-001', issueDate: '2024-01-15', lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }] });
  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paymentResult = recordPayment(issuedResult.value, { amount: 5899, date: '2024-01-20' });

  const result = dashboard([paymentResult.value], '2024-02-01');

  assert.equal(result.outstanding, 0);
  assert.equal(result.counts.paid, 1);
});

test('dashboard with mixed invoice statuses', () => {
  const draft = createInvoice({ customerId: 'C-001', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 10 }] }).value;
  const issued = issueInvoice(createInvoice({ customerId: 'C-001', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 10 }] }).value, []).value;
  const payment = recordPayment(issued, { amount: 40000, date: '2024-01-20' });

  const result = dashboard([draft, payment.value], '2024-02-01');

  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.partially_paid, 1);
  assert.ok(result.outstanding > 0);
});

test('dashboard structure is correct', () => {
  const invoices = [
    issueInvoice(createInvoice({ customerId: 'C-001', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 10 }] }).value, []).value,
  ];

  const result = dashboard(invoices, '2024-02-01');

  assert.ok('counts' in result);
  assert.ok('outstanding' in result);
  assert.ok('overdue' in result);
  assert.ok('topCustomers' in result);
  assert.ok('draft' in result.counts);
  assert.ok('issued' in result.counts);
  assert.ok('partially_paid' in result.counts);
  assert.ok('paid' in result.counts);
  assert.ok('count' in result.overdue);
  assert.ok('amount' in result.overdue);
});

test('dashboard topCustomers sorted by due descending', () => {
  const inv1 = issueInvoice(createInvoice({ customerId: 'C-005', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 1 }] }).value, []).value;
  const inv2 = issueInvoice(createInvoice({ customerId: 'C-006', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 10 }] }).value, ['INV-2024-0001']).value;
  const inv3 = issueInvoice(createInvoice({ customerId: 'C-007', issueDate: '2024-01-15', lines: [{ sku: 'DES-HOUR', qty: 5 }] }).value, ['INV-2024-0001', 'INV-2024-0002']).value;

  const result = dashboard([inv1, inv2, inv3], '2024-02-01');

  // C-006 (qty 10) > C-007 (qty 5) > C-005 (qty 1)
  assert.equal(result.topCustomers[0].customerId, 'C-006');
  assert.equal(result.topCustomers[1].customerId, 'C-007');
  assert.equal(result.topCustomers[2].customerId, 'C-005');
});

